// step3-chunk.js
var DAYS_PER_CHUNK = 7;
function enrichmentTokenLimitForChunk(daysInChunk) {
  const n = Number(daysInChunk) || 1;
  if (n <= 1) return 4e3;
  if (n <= 3) return 8e3;
  return 12e3;
}

