    if (/\bbarbell\b/.test(c)) return "\u0420\u0430\u043C\u0435\u043D\u043D\u043E \u0438\u0437\u0431\u0443\u0442\u0432\u0430\u043D\u0435 \u0441 \u0449\u0430\u043D\u0433\u0430";
