    if (/\bdumbbell\b/.test(c)) return "\u041C\u044A\u0440\u0442\u0432\u0430 \u0442\u044F\u0433\u0430 \u0441 \u0434\u044A\u043C\u0431\u0435\u043B\u0438";
    return "\u041C\u044A\u0440\u0442\u0432\u0430 \u0442\u044F\u0433\u0430";
