      strength: [[2, 0], [3, 0], [4, 0], [4, 1], [4, 2]],
      recomp: [[2, 0], [3, 0], [3, 1], [4, 1], [4, 2]],
      fat_loss: [[2, 0], [3, 0], [3, 1], [3, 2], [4, 2]],
