    forearm: "\u0440\u044A\u0446\u0435",
    core_flex: "\u043A\u043E\u0440\u0435\u043C",
    core_rot: "\u043A\u043E\u0440\u0435\u043C",
    core_static: "\u043A\u043E\u0440\u0435\u043C",
