  if (r.pregnant) safetyNotes.push("\u0411\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0441\u0442: \u0431\u0435\u0437 \u043B\u0435\u0433\u043D\u0430\u043B\u0438 \u043F\u043E \u0433\u0440\u044A\u0431 \u0443\u043F\u0440\u0430\u0436\u043D\u0435\u043D\u0438\u044F, \u043A\u043E\u0440\u0435\u043C\u043D\u0438 \u043F\u0440\u0435\u0441\u0438 \u0438 \u0441\u043A\u043E\u043A\u043E\u0432\u0435; \u0441\u043F\u0440\u0438 \u043F\u0440\u0438 \u0437\u0430\u043C\u0430\u0439\u0432\u0430\u043D\u0435 \u0438\u043B\u0438 \u0431\u043E\u043B\u043A\u0430.");
