    const sportStr = data.sportActivity;
    if (sportStr.includes("0 \u0434\u043D\u0438")) sportDays = 0;
    else if (sportStr.includes("1\u20132 \u0434\u043D\u0438")) sportDays = SPORT_DAYS_LOW;
