      currentIntake: current != null ? `${current} \u043B` : "\u043D\u0435 \u0435 \u043F\u043E\u0441\u043E\u0447\u0435\u043D",
      deficit: current != null ? `${Math.max(0, Math.round((need - current) * 10) / 10)} \u043B` : "\u2014",
