async function handleWeeklyGenerateQuestions(request, env) {
  try {
    if (!env.page_content) return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    const body = await request.json();
    const { userId, gameData, gameWeeklyAI, idToken } = body;
    if (!userId) {
      return jsonResponse2({ error: "Missing userId" }, 400);
    }
    try {
      await verifyWeeklyRequestAuth(userId, idToken, env);
    } catch (e) {
      return jsonResponse2({ error: e.message }, 401);
    }
    const { userData, plan, analytics, weeklyAdaptHistory } = await resolveWeeklyJobInputs(env, body);
    if (!plan?.weekPlan) {
      return jsonResponse2({ error: "Missing plan" }, 400);
    }
    if ((analytics.daysRecorded || 0) < 3) {
      return jsonResponse2({ error: "\u041D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u044A\u0447\u043D\u043E \u0434\u0430\u043D\u043D\u0438 \u0437\u0430 \u0441\u0435\u0434\u043C\u0438\u0447\u0435\u043D feedback (\u043C\u0438\u043D\u0438\u043C\u0443\u043C 3 \u0434\u043D\u0438)" }, 400);
    }
    const cycleNumber = (gameWeeklyAI?.cycleNumber || 0) + 1;
    const result = await generateWeeklyQuestions(
      env,
      userData,
      plan,
      analytics,
      { ...gameWeeklyAI, cycleNumber },
      weeklyAdaptHistory
    );
    return jsonResponse2({
      success: true,
      questions: result.questions,
      contextNote: result.contextNote,
      cycleNumber,
      analytics: {
        avgScore: analytics.avgScore,
        adherence: analytics.adherence,
        daysRecorded: analytics.daysRecorded
      }
    });
  } catch (error) {
    console.error("[WeeklyAdapt] generate-questions error:", error);
    return jsonResponse2({ error: error.message || "\u0413\u0440\u0435\u0448\u043A\u0430 \u043F\u0440\u0438 \u0433\u0435\u043D\u0435\u0440\u0438\u0440\u0430\u043D\u0435 \u043D\u0430 \u0432\u044A\u043F\u0440\u043E\u0441\u0438" }, 500);
  }
}
async function handleWeeklyAdaptPlan(request, env, ctx) {
  try {
    if (!env.page_content) return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    const body = await request.json();
    const { userId, gameData, gameWeeklyAI, answers, questions, clientId, idToken, userData, plan } = body;
    if (!userId || !answers?.length) {
      return jsonResponse2({ error: "Missing userId or answers" }, 400);
    }
    try {
      await verifyWeeklyRequestAuth(userId, idToken, env);
    } catch (e) {
      return jsonResponse2({ error: e.message }, 401);
    }
    const { plan: resolvedPlan } = await resolveWeeklyJobInputs(env, body);
    if (!resolvedPlan?.weekPlan) {
      return jsonResponse2({ error: "Missing plan" }, 400);
    }
    const existingProfile = await kvGetJSON(env, `user_profile:${userId}`);
    if (existingProfile?.pendingWeekly) {
      return jsonResponse2({ error: "\u0410\u0434\u0430\u043F\u0442\u0430\u0446\u0438\u044F \u0432\u0435\u0447\u0435 \u0435 \u0432 \u043F\u0440\u043E\u0446\u0435\u0441. \u041E\u043F\u0438\u0442\u0430\u0439\u0442\u0435 \u0441\u043B\u0435\u0434 \u043C\u0430\u043B\u043A\u043E." }, 409);
    }
    const jobId = crypto.randomUUID();
    const resolvedCycle = (gameWeeklyAI?.cycleNumber || 0) + 1;
    const payload = {
      userId,
      clientId: clientId || "",
      gameData,
      userData,
      plan: resolvedPlan,
      gameWeeklyAI: { ...gameWeeklyAI || {}, cycleNumber: resolvedCycle },
      answers,
      questions
    };
    if (env.PLAN_QUEUE) {
      await env.page_content.put(
        PLAN_JOB_PREFIX + jobId,
        JSON.stringify({ status: "pending", type: "weekly_adapt", startedAt: Date.now() }),
        { expirationTtl: PLAN_JOB_TTL_SEC }
      );
      await env.PLAN_QUEUE.send({ jobId, type: "weekly_adapt", payload }, { contentType: "json" });
    } else if (ctx) {
      ctx.waitUntil(runWeeklyAdaptation(env, payload, jobId));
    } else {
      return jsonResponse2({ error: "PLAN_QUEUE not configured" }, 503);
    }
    return jsonResponse2({ success: true, submitted: true, jobId, cycleNumber: resolvedCycle });
  } catch (error) {
    console.error("[WeeklyAdapt] adapt-plan error:", error);
    return jsonResponse2({ error: error.message }, 500);
  }
}
