async function handleRemoveGoalHack(request, env) {
  try {
    if (!env.page_content) {
      return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    }
    const data = await request.json();
    const { goal, index } = data;
    if (!goal || index === void 0) {
      return jsonResponse2({ error: "Goal and index are required" }, 400);
    }
    const hacks = await getAllGoalHacks(env);
    if (hacks[goal] && Array.isArray(hacks[goal]) && index >= 0 && index < hacks[goal].length) {
      hacks[goal].splice(index, 1);
      await saveGoalHacks(env, hacks);
    }
    return jsonResponse2({ success: true, hacks });
  } catch (error) {
    console.error("Error removing goal hack:", error);
    return jsonResponse2({ error: `Failed to remove goal hack: ${error.message}` }, 500);
  }
}
