async function handleSaveUserProfile(request, env) {
  try {
    if (!env.page_content) {
      return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    }
    const { userId, plan, userData, planSource, idToken, clientId } = await request.json();
    if (!userId || !plan) {
      return jsonResponse2({ error: "Missing userId or plan" }, 400);
    }
    if (userId.startsWith("fb_") && idToken && env.FIREBASE_PROJECT_ID) {
      try {
        const firebaseUser = await verifyFirebaseIdToken(idToken, env);
        if ("fb_" + firebaseUser.uid !== userId) {
          return jsonResponse2({ error: "Token does not match userId" }, 403);
        }
      } catch (_) {
        return jsonResponse2({ error: "Invalid Firebase ID token" }, 401);
      }
    }
    const existingProfile = await kvGetJSON(env, `user_profile:${userId}`);
    const planChanged = !existingProfile?.plan || JSON.stringify(existingProfile.plan) !== JSON.stringify(plan);
    const now = (/* @__PURE__ */ new Date()).toISOString();
    const profileData = {
      userId,
      plan,
      userData: userData || {},
      planSource: planSource || "",
      // clientId links a questionnaire-2 submission to its client record so that
      // plan-pending.html can check plan status when the user logs in on a new device.
      ...clientId ? { clientId } : {},
      savedAt: now,
      planUpdatedAt: planChanged ? now : existingProfile?.planUpdatedAt || existingProfile?.savedAt || now
    };
    const ttl = userId.startsWith("fb_") ? 365 * 24 * 60 * 60 : 90 * 24 * 60 * 60;
    const normalizedEmail = normalizeEmail(profileData.userData?.email);
    let resolvedClientId = clientId || "";
    if (!resolvedClientId && normalizedEmail) {
      resolvedClientId = (await findClientByEmail(env, normalizedEmail))?.clientId || "";
    }
    await kvPutJSON(env, `user_profile:${userId}`, profileData, ttl);
    if (normalizedEmail) {
      try {
        const syncResult = await syncPlanToEmailCanonicalStore(env, {
          email: normalizedEmail,
          ...planChanged && plan ? { plan } : {},
          userData: profileData.userData,
          userId,
          clientId: resolvedClientId || profileData.clientId || "",
          requireApproval: planChanged && profileData.planSource === "questionnaire2"
        });
        if (syncResult?.clientId && !profileData.clientId) {
          profileData.clientId = syncResult.clientId;
          await kvPutJSON(env, `user_profile:${userId}`, profileData, ttl);
        }
      } catch (e) {
        console.warn(`Failed to sync profile for ${userId}:`, e.message);
      }
    }
    console.log(`User profile saved for restore: ${userId}`);
    return jsonResponse2({ success: true, planUpdatedAt: profileData.planUpdatedAt });
  } catch (error) {
    console.error("Error saving user profile:", error);
    return jsonResponse2({ error: "Failed to save user profile: " + error.message }, 500);
  }
}
