async function handleGetPlanVersion(request, env) {
  try {
    if (!env.page_content) {
      return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    }
    const url = new URL(request.url);
    const resolvedUserId = (url.searchParams.get("userId") || "").trim();
    if (!resolvedUserId) {
      return jsonResponse2({ error: "Missing userId" }, 400);
    }
    if (resolvedUserId.startsWith("fb_") && env.FIREBASE_PROJECT_ID) {
      const authHeader = request.headers.get("Authorization") || "";
      const idToken = authHeader.startsWith("Bearer ") ? authHeader.slice(7) : null;
      if (idToken) {
        try {
          const firebaseUser = await verifyFirebaseIdToken(idToken, env);
          if ("fb_" + firebaseUser.uid !== resolvedUserId) {
            return jsonResponse2({ error: "Token does not match userId" }, 403);
          }
        } catch (_) {
          return jsonResponse2({ error: "Invalid Firebase ID token" }, 401);
        }
      }
    }
    const profile = await kvGetJSON(env, `user_profile:${resolvedUserId}`);
    if (!profile?.plan) {
      return jsonResponse2({ found: false }, 404);
    }
    if (!isPlanEditingAllowed({
      userId: resolvedUserId,
      clientId: profile.clientId,
      email: profile.userData?.email
    })) {
      return planEditingBlockedResponse();
    }
    const releasedProfile = await applyWeeklyReleaseIfDue(env, profile, resolvedUserId);
    const planUpdatedAt = getEffectivePlanUpdatedAt(releasedProfile);
    const clientVersion = (url.searchParams.get("v") || "").trim();
    if (clientVersion && planUpdatedAt && clientVersion >= planUpdatedAt) {
      return jsonResponse2({
        found: true,
        upToDate: true,
        planUpdatedAt,
        ...releasedProfile.weeklyAdaptNotice ? { weeklyAdaptNotice: releasedProfile.weeklyAdaptNotice } : {}
      });
    }
    return jsonResponse2({
      found: true,
      planUpdatedAt,
      ...releasedProfile.weeklyAdaptNotice ? { weeklyAdaptNotice: releasedProfile.weeklyAdaptNotice } : {}
    });
  } catch (error) {
    console.error("Error getting plan version:", error);
    return jsonResponse2({ error: "Failed to get plan version: " + error.message }, 500);
  }
}
async function handleGetUserProfile(request, env) {
  try {
    if (!env.page_content) {
      return jsonResponse2({ error: ERROR_MESSAGES.KV_NOT_CONFIGURED }, 500);
    }
    const url = new URL(request.url);
    let resolvedUserId = url.searchParams.get("userId");
    if (!resolvedUserId) {
      return jsonResponse2({ error: "Missing userId" }, 400);
    }
    if (resolvedUserId.startsWith("fb_") && env.FIREBASE_PROJECT_ID) {
      const authHeader = request.headers.get("Authorization") || "";
      const idToken = authHeader.startsWith("Bearer ") ? authHeader.slice(7) : null;
      if (idToken) {
        try {
          const firebaseUser = await verifyFirebaseIdToken(idToken, env);
          if ("fb_" + firebaseUser.uid !== resolvedUserId) {
            return jsonResponse2({ error: "Token does not match userId" }, 403);
          }
        } catch (_) {
          return jsonResponse2({ error: "Invalid Firebase ID token" }, 401);
        }
      }
    }
    const requestedEmail = normalizeEmail(url.searchParams.get("email"));
    let profile = await kvGetJSON(env, `user_profile:${resolvedUserId}`);
    if (requestedEmail) {
      const emailIndex = await getEmailIndex(env, requestedEmail);
      if (emailIndex?.userId && emailIndex.userId !== resolvedUserId) {
        const canonicalProfile = await kvGetJSON(env, `user_profile:${emailIndex.userId}`);
        if (canonicalProfile?.plan) {
          profile = canonicalProfile;
          resolvedUserId = emailIndex.userId;
        }
      }
      if (!profile?.plan && emailIndex?.clientId) {
        const clientData = await kvGetJSON(env, `client:${emailIndex.clientId}`);
        if (clientData?.plan) {
          profile = {
            userId: emailIndex.userId || resolvedUserId,
            plan: clientData.plan,
            userData: clientData.answers || {},
            planSource: clientData.planStatus === "activated" ? "" : "questionnaire2",
            clientId: emailIndex.clientId,
            savedAt: (/* @__PURE__ */ new Date()).toISOString(),
            planUpdatedAt: clientData.planUpdatedAt || clientData.planActivatedAt || (/* @__PURE__ */ new Date()).toISOString()
          };
          if (emailIndex.userId) resolvedUserId = emailIndex.userId;
        }
      }
    }
    if (!profile && requestedEmail) {
      const matchedClient = await findClientByEmail(env, requestedEmail);
      if (matchedClient) {
        const clientData = matchedClient.clientData;
        if (resolvedUserId && clientData.userId !== resolvedUserId) {
          clientData.userId = resolvedUserId;
          await kvPutJSON(env, `client:${matchedClient.clientId}`, clientData, null);
        }
        profile = {
          userId: resolvedUserId || clientData.userId || "",
          plan: clientData.plan || null,
          userData: clientData.answers || {},
          planSource: clientData.planStatus === "activated" ? "" : "questionnaire2",
          clientId: matchedClient.clientId,
          savedAt: (/* @__PURE__ */ new Date()).toISOString(),
          planUpdatedAt: clientData.planUpdatedAt || clientData.planActivatedAt || (/* @__PURE__ */ new Date()).toISOString()
        };
        const ttl = resolvedUserId && resolvedUserId.startsWith("fb_") ? 365 * 24 * 60 * 60 : 90 * 24 * 60 * 60;
        if (resolvedUserId) {
          await kvPutJSON(env, `user_profile:${resolvedUserId}`, profile, ttl);
        }
      }
    }
    if (!profile) {
      return jsonResponse2({ found: false }, 404);
    }
    let planSource = profile.planSource || "";
    let clientId = profile.clientId || "";
    if (planSource === "questionnaire2") {
      let linkedClient = null;
      if (clientId) {
        linkedClient = await kvGetJSON(env, `client:${clientId}`);
      }
      if (linkedClient?.planStatus === "pending") {
        if (linkedClient.plan) profile.plan = linkedClient.plan;
        profile.planUpdatedAt = linkedClient.planUpdatedAt || profile.planUpdatedAt;
        if (clientId) profile.clientId = clientId;
      } else {
        let activatedClient = linkedClient;
        if (activatedClient?.planStatus !== "activated" && profile.userData?.email) {
          const wantedEmail = String(profile.userData.email).trim().toLowerCase();
          const clientIds = await kvGetJSON(env, "clients_list") || [];
          for (const id of clientIds.slice(0, 500)) {
            const clientData = await kvGetJSON(env, `client:${id}`);
            if (!clientData) continue;
            if (clientData.planStatus !== "activated" || !clientData.plan) continue;
            if (clientData.planReplacementPending) continue;
            const clientEmail = String(clientData.answers?.email || "").trim().toLowerCase();
            if (clientEmail === wantedEmail) {
              activatedClient = clientData;
              clientId = id;
              break;
            }
          }
        }
        if (activatedClient?.planStatus === "activated" && !activatedClient.planReplacementPending) {
          if (activatedClient.plan) profile.plan = activatedClient.plan;
          profile.planSource = "";
          if (clientId) profile.clientId = clientId;
          planSource = "";
          await kvPutJSON(env, `user_profile:${resolvedUserId}`, profile, null);
        } else if (clientId) {
          profile.clientId = clientId;
        }
      }
    }
    profile = await applyWeeklyReleaseIfDue(env, profile, resolvedUserId);
    if (!isPlanEditingAllowed({
      userId: resolvedUserId,
      clientId: profile.clientId || clientId,
      email: profile.userData?.email || requestedEmail
    }) && (profile.plan || profile.clientId || planSource === "questionnaire2")) {
      return planEditingBlockedResponse();
    }
    const planUpdatedAt = getEffectivePlanUpdatedAt(profile);
    return jsonResponse2({
      found: true,
      plan: profile.plan,
      userData: profile.userData,
      planSource,
      planUpdatedAt,
      ...profile.weeklyAdaptNotice ? { weeklyAdaptNotice: profile.weeklyAdaptNotice } : {},
      ...clientId ? { clientId } : {}
    });
  } catch (error) {
    console.error("Error getting user profile:", error);
    return jsonResponse2({ error: "Failed to get user profile: " + error.message }, 500);
  }
}
